/**
 * s2B-sw1: single-pose Bria background removal
 * Input: one pose item from 2B main
 */
const j = $json || {};
const pick = (...v) => v.find(x => x !== undefined && x !== null && x !== '');

const orderId = pick(j.orderId, null);
const characterHash = pick(j.characterHash, null);
const poseNumberRaw = pick(j.poseNumber, null);
const poseNumber = (poseNumberRaw === 0 || poseNumberRaw === '0') ? 0 : Number(poseNumberRaw);
const approvedKey = pick(j.approvedKey, null);

if (!orderId) throw new Error('s2B-sw1: orderId required');
if (!characterHash) throw new Error('s2B-sw1: characterHash required');
if (!Number.isFinite(poseNumber)) throw new Error('s2B-sw1: poseNumber required');
if (!approvedKey) throw new Error('s2B-sw1: approvedKey required');

const backendUrl = pick(j.backendUrl, 'https://admin.littleherolabs.com');
const callbackUrl = pick(j.callbackUrl, `${backendUrl}/webhook/2b-callback`);

const replacedAt = pick(j.replacedAt, null);
const replacementCount = Number(pick(j.replacementCount, 0) || 0);
const manifest2aUrl = pick(j.manifest2aUrl, null);

// Build a replacement-aware cache-busted source URL via backend proxy (private bucket-safe)
const replacedAtMs = replacedAt ? Date.parse(String(replacedAt)) : NaN;
const v = Number.isFinite(replacedAtMs) ? replacedAtMs : (replacementCount > 0 ? replacementCount : Date.now());
const sourceUrl = `${backendUrl}/api/assets/${approvedKey}?v=${v}`;

return [{ json: {
  orderId, characterHash, poseNumber, approvedKey,
  backendUrl, callbackUrl,
  replacedAt, replacementCount, manifest2aUrl,
  sourceUrl
} }];

/**
 * Build Bria remove-bg request payload (JSON).
 * Bria API v2 expects 'image' field (can be URL or base64)
 * Uses backend proxy endpoint for R2 images (required for private R2)
 * Handles URL normalization and fallbacks like original workflow
 */
const j = $json || {};

// Backend API configuration
const backendUrl = j.backendUrl || 'https://admin.littleherolabs.com';

// Helper function to normalize malformed URLs
function normalizeUrl(url) {
  if (!url || typeof url !== 'string') return url;
  // Fix: https:/domain -> https://domain
  url = url.replace(/^https:\/(?!\/)/, 'https://');
  url = url.replace(/^http:\/(?!\/)/, 'http://');
  return url;
}

// Get URL from sourceUrl (built in Normalize Input)
let url = j.sourceUrl || null;

// Normalize URL to fix malformed URLs
if (url) {
  url = normalizeUrl(url);
}

// Base64 fallback (shouldn't be needed with manifest)
let b64 = j.extractedImageData || j.poseBase64 || j.characterBase64 || null;
if (typeof b64 === 'string') {
  const m = b64.match(/^data:(image\/[a-z0-9+.\-]+);base64,(.*)$/i);
  if (m) b64 = m[2];
  b64 = b64.trim();
  if (b64.length < 12) b64 = null;
}

if (!url && !b64) {
  throw new Error(`Pose ${j.poseNumber || 'unknown'}: No usable image URL found`);
}

// Build Bria payload (matches original workflow structure)
const briaPayload = {
  image: url || b64,
  meta: {
    correlationId: j.correlationId || null,
    pose: j.poseNumber || null,
    characterHash: j.characterHash || null,
    source: url ? 'url' : 'base64'
  }
};

const urlType = url ? (url.includes('/api/assets/') ? 'backend proxy URL' : 'public URL') : 'base64 data';
console.log(`Pose ${j.poseNumber || 'unknown'}: Using ${url ? 'URL' : 'base64'} - ${urlType}`);

return [{ json: { ...j, bria: { payload: briaPayload }, briaSource: url ? 'url' : 'base64' } }];

/**
 * Extract Bria status URL/requestId and begin bounded polling loop state.
 */
const resp = $json || {};
let ctx = {};
try { ctx = $items('Normalize Input', 0, $runIndex)?.[0]?.json || {}; } catch {}

const statusUrl = resp.status_url || resp.statusUrl || resp.data?.status_url || null;
const requestId = resp.request_id || resp.requestId || resp.data?.request_id || null;
if (!statusUrl && !requestId) {
  throw new Error('s2B-sw1: Bria submit did not return status_url/request_id');
}

return [{ json: { ...ctx, briaStatusUrl: statusUrl, briaRequestId: requestId, attempt: 0 } }];

/**
 * Decide: continue polling vs completed vs failed/timeout.
 * Updated for Bria API v2 response format: { result: { image_url }, status, request_id }
 */
const poll = $json || {};
let ctx = {};
try { ctx = $items('Extract Bria Tracking', 0, $runIndex)?.[0]?.json || {}; } catch {}

const maxAttempts = 20;
const attempt = Number(ctx.attempt || 0) + 1;

// Status: v2 uses uppercase (COMPLETED), v1 uses lowercase (completed)
const statusRaw = poll.status || poll.state || poll.data?.status || '';
const status = String(statusRaw).toLowerCase();

// Result URL: v2 has result.image_url, v1 has result_url/resultUrl
const resultUrl = poll.result?.image_url ||
                  poll.result_url ||
                  poll.resultUrl ||
                  poll.data?.result_url ||
                  poll.data?.resultUrl ||
                  poll.data?.result?.image_url ||
                  null;

const errMsg = poll.error?.message || poll.message || poll.data?.error || null;

// Normalize terminal states
if (status === 'completed' || status === 'done' || (resultUrl && !status)) {
  if (!resultUrl) throw new Error('s2B-sw1: completed but missing result_url');
  return [{ json: { ...ctx, attempt, briaStatus: 'completed', briaResultUrl: resultUrl, briaErrorMessage: null } }];
}
if (status === 'failed' || status === 'error') {
  return [{ json: { ...ctx, attempt, briaStatus: 'failed', briaResultUrl: null, briaErrorMessage: errMsg || 'Bria failed' } }];
}

if (attempt >= maxAttempts) {
  return [{ json: { ...ctx, attempt, briaStatus: 'timeout', briaResultUrl: null, briaErrorMessage: `Timeout after ${maxAttempts} polls` } }];
}

// Continue polling
return [{ json: { ...ctx, attempt, briaStatus: 'polling', briaResultUrl: null } }];

// Emits where to fetch the neon canvas from, and what to name its binary
return [{
  json: {
    bgBucket: 'little-hero-assets',
    bgKey: 'book-mvp-simple-adventure/backgrounds/transparency-qa/neon-background.png',
    bgBinary: 'bg'
  }
}];

/**
 * Transparency QA Build Request — dual-image (composite + original) & filesystem-safe
 * Expects:
 *   - composite image under binary.bg  (from Edit Image → Composite base)
 *   - original cutout under binary.data (transparent PNG)
 * Emits:
 *   - json.geminiRequest (ready to POST)
 *   - drops binaries to keep memory low
 */

const idx = $itemIndex;
const bin = $input.item.binary || {};

const hasComposite = !!bin.bg;
const hasOriginal  = !!bin.data;
const compositeKey = hasComposite ? 'bg'   : Object.keys(bin)[0];
const originalKey  = hasOriginal  ? 'data' : Object.keys(bin)[1] || Object.keys(bin)[0];

if (!compositeKey || !originalKey || !bin[compositeKey] || !bin[originalKey]) {
  throw new Error('Expected binary.bg (composite) and binary.data (original) to be present.');
}

const mimeComposite = bin[compositeKey].mimeType || 'image/png';
const mimeOriginal  = bin[originalKey].mimeType  || 'image/png';

const compBuf = await this.helpers.getBinaryDataBuffer(idx, compositeKey);
const origBuf = await this.helpers.getBinaryDataBuffer(idx, originalKey);

const compB64 = compBuf.toString('base64');
const origB64 = origBuf.toString('base64');

const qaPrompt = `
Task: QA for accidental removal of EYES or TEETH during background removal.

You are given two images:
1) A composite image of the subject over a solid neon green background (#39FF14, RGB 57,255,20).
2) The original PNG with a transparent background (has alpha channel).

Rules (be strict):
- Treat image 1 as the primary evidence for interior holes and missing facial pixels.
- Use image 2 as a secondary reference for the original silhouette and intended facial structure.
- Focus on the FACE area. Specifically inspect: left eye, right eye, and mouth/teeth area.
- If an eye looks accidentally erased/removed/cut out, set "needs_review": true and add an issue starting with:
  "MISSING_EYE_LEFT" or "MISSING_EYE_RIGHT".
- If teeth look accidentally erased/removed/cut out (only when teeth are intended/visible), set "needs_review": true and add:
  "MISSING_TEETH".
- Also flag accidental transparency holes INSIDE the silhouette: if neon green (#39FF14, ±5% tolerance) is visible inside the
  subject silhouette (especially eyes/teeth/mouth), set "needs_review": true and add "INTERIOR_HOLE".
- Use the original PNG's alpha as a guide for the silhouette. Ignore the outer green area and a 1–3 px antialias halo.
- Do NOT flag for legitimate cases: side profile / hair occlusion, eyes closed/blink, mouth closed/no teeth visible.
- If uncertain, set "needs_review": true.

Return strict JSON only (no markdown):
{"needs_review": true|false, "issues": ["..."], "confidence": 0..1}
`.trim();

const geminiRequest = {
  contents: [{
    role: "user",
    parts: [
      { text: qaPrompt },
      { inline_data: { mime_type: mimeComposite, data: compB64 } },
      { inline_data: { mime_type: mimeOriginal,  data: origB64 } }
    ]
  }],
  generationConfig: {
    response_mime_type: "application/json",
    temperature: 0,
    topP: 0
  }
};

return {
  json: {
    ...$json,
    qa: { ...( $json.qa || {} ), transparency: { requested: true, bgHex: "#39FF14" } },
    geminiRequest
  },
  binary: {}
};

/**
 * Parse Transparency QA Result (single item)
 * Recall-biased: fail if parse fails or confidence < 0.90
 */
function extractText(resp) {
  try {
    const parts = resp?.candidates?.[0]?.content?.parts || [];
    return parts.map(p => (p && typeof p.text === 'string' ? p.text : '')).join('\n').trim();
  } catch {
    return '';
  }
}

const CONF_FLOOR = 0.90;
const TOKEN_RE = /^(MISSING_EYE_LEFT|MISSING_EYE_RIGHT|MISSING_TEETH)\b/;

const resp = $json || {};
const raw = extractText(resp);

let parsed = null;
try { parsed = raw ? JSON.parse(raw) : null; } catch { parsed = null; }

const needsReviewModel = parsed?.needs_review === true;
const confidence = Number.isFinite(parsed?.confidence) ? parsed.confidence : null;

let issues = Array.isArray(parsed?.issues)
  ? parsed.issues
  : (raw ? [raw] : []);
issues = issues
  .map((v) => (typeof v === 'string' ? v : (() => { try { return JSON.stringify(v); } catch { return String(v); } })()))
  .map((s) => String(s || '').trim())
  .filter(Boolean);

const parseFailed = !parsed;
if (parseFailed) {
  const snippet = raw ? raw.substring(0, 200) : '';
  issues = [snippet ? `PARSE_FAIL: ${snippet}` : 'PARSE_FAIL: empty_or_unparseable'];
}

const tokens = issues.filter((s) => TOKEN_RE.test(s));

const needsReview = needsReviewModel || parseFailed || confidence === null || confidence < CONF_FLOOR;

if (needsReview && issues.length === 0) {
  issues = [parseFailed ? 'PARSE_FAIL: empty_or_unparseable' : 'LOW_CONFIDENCE'];
}

const out = {
  ...$json,
  qa: {
    ...($json.qa || {}),
    transparency: { pass: !needsReview, issues, confidence }
  },
  needsReview,
  reviewReason: tokens.length > 0
    ? 'missing_eyes_or_teeth'
    : (needsReview ? 'transparency_fail_or_low_conf' : null),
};

// trim heavy fields
delete out.candidates; delete out.usageMetadata; delete out.modelVersion; delete out.responseId;

// For runOnceForEachItem mode, return single object, not array
return { json: out };

/**
 * Mark as Needs Review - Set additional tracking fields for failed QA cases
 * Matches original workflow's "Mark as Needs Review" node behavior
 */
const j = $json || {};

// Mark as failed
j.qaPass = false;
j.success = false;
j.qa = j.qa || {};
j.qa.combined = { pass: false };

// Track for backend
j.needsReview = true;
j.reviewReason = j.reviewReason || 'transparency_fail';
j.route = 'manual_review';

// Ensure retryAttempt shows exhausted (at least 3)
j.retryAttempt = Math.max(j.retryAttempt || 0, j.retry?.attempt || 0, 3);

// For runOnceForEachItem mode, return single object, not array
return { json: j, binary: {} };

/**
 * Drop Heavy Fields - Remove large data fields to reduce memory
 * Preserves essential metadata for callback
 */
const j = $json || {};

const cleaned = { ...j };
// Remove heavy fields that aren't needed downstream
delete cleaned.extractedImageData;
delete cleaned.poseBase64;
delete cleaned.characterBase64;
delete cleaned.requestBody;
delete cleaned.geminiRequest; // Already processed
// Preserve: poseNumber, orderId, characterHash, briaStatus, qa, needsReview, etc.

// For runOnceForEachItem mode, return single object, not array
return { json: cleaned, binary: {} };

/**
 * Prepare canonical R2 key and minimal metadata.
 * Preserves binary data for upload.
 * Uses legacy path structure: book-mvp-simple-adventure/order-generated-assets/characters/{hash}/characters_{hash}_pose{NN}_nobg.png
 */
const j = $json || {};
const bin = $binary || {};

// Validate required fields
if (!j.characterHash) {
  throw new Error('Prep Upload: characterHash is required');
}
if (!Number.isFinite(j.poseNumber)) {
  throw new Error('Prep Upload: poseNumber is required');
}

const BASE_PREFIX = 'book-mvp-simple-adventure/order-generated-assets/characters';
const characterHash = String(j.characterHash);
const poseNN = String(j.poseNumber).padStart(2, '0');
const fileName = `characters_${characterHash}_pose${poseNN}_nobg.png`;
const bgRemovedKey = `${BASE_PREFIX}/${characterHash}/${fileName}`;

return [{ 
  json: { ...j, poseNN, bgRemovedKey, briaCompletedAt: new Date().toISOString() },
  binary: bin
}];

/**
 * Clean Binary After Upload - Return complete result for orchestrator aggregator
 * Preserves all fields needed for manifest update
 * Handles case where S3 upload node strips JSON data
 */
const j = $json || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// S3 upload node may strip JSON - retrieve from upstream nodes
let poseNumber = Number(j.poseNumber);
let bgRemovedKey = j.bgRemovedKey;
let orderId = j.orderId;
let characterHash = j.characterHash;
let briaCompletedAt = j.briaCompletedAt;
let qa = j.qa;
let needsReview = j.needsReview;
let reviewReason = j.reviewReason;
let briaStatus = j.briaStatus;
let briaRequestId = j.briaRequestId;
let briaStatusUrl = j.briaStatusUrl;
let briaErrorMessage = j.briaErrorMessage;
let backendUrl = j.backendUrl;
let manifest2aUrl = j.manifest2aUrl;
let approvedKey = j.approvedKey;
let replacedAt = j.replacedAt;
let replacementCount = j.replacementCount;
let sourceUrl = j.sourceUrl;

// Fallback 1: Try from Prep Upload node (most reliable source)
if (!bgRemovedKey || !Number.isFinite(poseNumber) || poseNumber < 0) {
  try {
    const prepItems = $items('Prep Upload', 0, runIx);
    if (prepItems?.length) {
      const prep = prepItems[0]?.json || {};
      if (!bgRemovedKey) bgRemovedKey = prep.bgRemovedKey;
      if (!Number.isFinite(poseNumber) || poseNumber < 0) {
        const prepPose = Number(prep.poseNumber);
        if (Number.isFinite(prepPose) && prepPose >= 0) {
          poseNumber = prepPose;
        }
      }
      if (!orderId) orderId = prep.orderId;
      if (!characterHash) characterHash = prep.characterHash;
      if (!briaCompletedAt) briaCompletedAt = prep.briaCompletedAt;
    }
  } catch {}
}

// Fallback 2: Try from Merge QA with Binary node
if (!bgRemovedKey || !Number.isFinite(poseNumber) || poseNumber < 0 || !briaStatus) {
  try {
    const mergeItems = $items('Merge QA with Binary', 0, runIx);
    if (mergeItems?.length) {
      const merge = mergeItems[0]?.json || {};
      if (!bgRemovedKey) bgRemovedKey = merge.bgRemovedKey;
      if (!Number.isFinite(poseNumber) || poseNumber < 0) {
        const mergePose = Number(merge.poseNumber);
        if (Number.isFinite(mergePose) && mergePose >= 0) {
          poseNumber = mergePose;
        }
      }
      if (!orderId) orderId = merge.orderId;
      if (!characterHash) characterHash = merge.characterHash;
      if (!qa) qa = merge.qa;
      if (needsReview === undefined) needsReview = merge.needsReview;
      if (!reviewReason) reviewReason = merge.reviewReason;
      if (!briaStatus) briaStatus = merge.briaStatus;
    }
  } catch {}
}

// Fallback 2.5: Try from Preserve Binary Path Context node (has briaStatus after download)
if (!briaStatus || briaStatus === 'error') {
  try {
    const preserveItems = $items('Preserve Binary Path Context', 0, runIx);
    if (preserveItems?.length) {
      const preserve = preserveItems[0]?.json || {};
      if (preserve.briaStatus && preserve.briaStatus !== 'error') {
        briaStatus = preserve.briaStatus;
        if (!briaRequestId) briaRequestId = preserve.briaRequestId;
        if (!briaStatusUrl) briaStatusUrl = preserve.briaStatusUrl;
        if (!briaResultUrl && preserve.briaResultUrl) {
          // briaResultUrl is not used downstream but good to preserve
        }
      }
    }
  } catch {}
}

// Fallback 2.6: Try from Decide Poll node (source of truth for briaStatus)
if (!briaStatus || briaStatus === 'error') {
  try {
    const decideItems = $items('Decide Poll', 0, runIx);
    if (decideItems?.length) {
      // Find the completed one (should be the last one)
      const decide = decideItems.find(item => item.json.briaStatus === 'completed') || decideItems[decideItems.length - 1];
      if (decide?.json?.briaStatus) {
        briaStatus = decide.json.briaStatus;
        if (!briaRequestId) briaRequestId = decide.json.briaRequestId;
        if (!briaStatusUrl) briaStatusUrl = decide.json.briaStatusUrl;
        if (!briaResultUrl && decide.json.briaResultUrl) {
          // briaResultUrl is not used downstream but good to preserve
        }
      }
    }
  } catch {}
}

// Fallback 3: Try from Normalize Input node (for context fields)
if (!Number.isFinite(poseNumber) || poseNumber < 0 || !orderId || !characterHash || !backendUrl || !manifest2aUrl) {
  try {
    const normItems = $items('Normalize Input', 0, runIx);
    if (normItems?.length) {
      const norm = normItems[0]?.json || {};
      if (!Number.isFinite(poseNumber) || poseNumber < 0) {
        const normPose = Number(norm.poseNumber);
        if (Number.isFinite(normPose) && normPose >= 0) {
          poseNumber = normPose;
        }
      }
      if (!orderId) orderId = norm.orderId;
      if (!characterHash) characterHash = norm.characterHash;
      if (!backendUrl) backendUrl = norm.backendUrl;
      if (!manifest2aUrl) manifest2aUrl = norm.manifest2aUrl;
      if (!approvedKey) approvedKey = norm.approvedKey;
      if (!replacedAt) replacedAt = norm.replacedAt;
      if (replacementCount === undefined) replacementCount = norm.replacementCount;
      if (!sourceUrl) sourceUrl = norm.sourceUrl;
    }
  } catch {}
}

// Fallback 4: Try from Extract Bria Tracking node (for Bria tracking fields)
if (!briaRequestId || !briaStatusUrl) {
  try {
    const trackItems = $items('Extract Bria Tracking', 0, runIx);
    if (trackItems?.length) {
      const track = trackItems[0]?.json || {};
      if (!briaRequestId) briaRequestId = track.briaRequestId;
      if (!briaStatusUrl) briaStatusUrl = track.briaStatusUrl;
    }
  } catch {}
}

// Validate required fields
if (!Number.isFinite(poseNumber) || poseNumber < 0) {
  throw new Error(`Invalid poseNumber: ${j.poseNumber || 'undefined'}`);
}

if (!orderId) throw new Error(`Missing orderId for pose ${poseNumber}`);
if (!characterHash) throw new Error(`Missing characterHash for pose ${poseNumber}`);

// Set defaults
if (!backendUrl) backendUrl = 'https://admin.littleherolabs.com';
if (!briaStatus) briaStatus = 'error';

// Set briaCompletedAt if completed and missing
const isCompleted = briaStatus === 'completed';
if (isCompleted && !briaCompletedAt) {
  briaCompletedAt = new Date().toISOString();
}

// Set bgRemovedKey only if completed
if (!isCompleted) {
  bgRemovedKey = null;
}

console.log(`[Pose ${poseNumber}] ✓ Uploaded to R2: ${bgRemovedKey || 'N/A (not completed)'}`);

// Build complete result object with all fields needed by aggregator
const result = {
  orderId,
  characterHash,
  poseNumber,
  approvedKey: approvedKey || null,
  sourceReplacedAt: replacedAt || null,
  sourceReplacementCount: Number(replacementCount || 0),
  sourceUrl: sourceUrl || null,
  manifest2aUrl: manifest2aUrl || null,
  backendUrl,
  briaStatus,
  briaRequestId: briaRequestId || null,
  briaStatusUrl: briaStatusUrl || null,
  briaCompletedAt: isCompleted ? (briaCompletedAt || new Date().toISOString()) : null,
  briaErrorMessage: isCompleted ? null : (briaErrorMessage || null),
  bgRemovedKey: isCompleted ? (bgRemovedKey || null) : null,
  bgRemovedContentType: isCompleted ? 'image/png' : null,
  bgRemovedSizeBytes: null,
  bgRemovedImageUrl: null,
  qa: (qa && typeof qa === 'object') ? qa : null,
  needsReview: (needsReview === true) ? true : (!isCompleted),
  reviewReason: (needsReview === true)
    ? (reviewReason || 'transparency_fail_or_low_conf')
    : (isCompleted ? null : (briaStatus === 'timeout' ? 'bria_timeout' : 'bria_failed')),
};

// For runOnceForEachItem mode, return single object, not array
return { 
  json: result,
  binary: {} // Clear binary data
};

/**
 * Preserve Binary Path Context - Ensure JSON context is preserved with binary
 * This node ensures poseNumber, orderId, characterHash, briaStatus, etc. are maintained
 * along with the binary data for the Merge QA with Binary node
 * HTTP download node overwrites JSON, so we recover context from upstream nodes
 */
const j = $json || {};
const bin = $binary || {};
const runIx = (typeof $runIndex === 'number') ? $runIndex : 0;

// Recover context from Decide Poll or If Completed node (briaStatus is set there)
let ctx = {};
try {
  const decideItems = $items('Decide Poll', 0, runIx);
  if (decideItems?.length) {
    const decide = decideItems.find(item => item.json.briaStatus === 'completed') || decideItems[0];
    if (decide?.json) {
      ctx = { ...decide.json };
    }
  }
} catch {}

// If not found, try If Completed node
if (!ctx.briaStatus) {
  try {
    const ifCompletedItems = $items('If Completed', 0, runIx);
    if (ifCompletedItems?.length) {
      const ifCompleted = ifCompletedItems[0]?.json || {};
      if (ifCompleted.briaStatus) {
        ctx = { ...ctx, ...ifCompleted };
      }
    }
  } catch {}
}

// Merge recovered context with current JSON (current JSON may have binary metadata)
const preserved = {
  ...ctx,  // Recovered context (has briaStatus, briaResultUrl, etc.)
  ...j     // Current JSON (may have binary file metadata)
};

// Preserve all JSON fields and binary data
return [{ 
  json: preserved,
  binary: bin
}];
